    child.stderr.on("data", (chunk) => {
      stderr += chunk.toString();
    });
    child.on("error", (error51) => {
      clearTimeout(timeout);
      reject(error51);
    });
    child.on("close", (code) => {
      clearTimeout(timeout);
      emitLines("", true);
      resolve({ exitCode: code ?? -1, stdout, stderr });
    });
